import React from "react";

// Spice-inspired palettes: saffron, chili red, turmeric, curry-leaf green.
const PALETTES = [
  ["#EFA23A", "#C43D1F", "#4B7A4F"],
  ["#C43D1F", "#1F4A3B", "#E8B923"],
  ["#E8B923", "#4B7A4F", "#8A2E12"],
];

export default function DishArt({ seed = 0 }) {
  const p = PALETTES[seed % PALETTES.length];
  return (
    <svg viewBox="0 0 200 120" style={{ width: "100%", height: 100, borderRadius: 14, background: "var(--bg)" }}>
      <ellipse cx="100" cy="90" rx="86" ry="18" fill={p[0]} opacity="0.25" />
      <ellipse cx="100" cy="70" rx="78" ry="30" fill="#FFFCF6" />
      {/* curry / gravy base */}
      <ellipse cx="100" cy="66" rx="72" ry="24" fill={p[0]} opacity="0.88" />
      {/* garnish: paneer / veg pieces */}
      <circle cx="70" cy="58" r="10" fill={p[1]} />
      <circle cx="110" cy="50" r="8" fill={p[2]} />
      <circle cx="130" cy="66" r="7" fill="#241209" />
      <circle cx="90" cy="70" r="7" fill="#FBF1E1" />
      {/* fresh coriander fleck */}
      <circle cx="105" cy="62" r="3" fill="#3B6B4A" />
      <circle cx="80" cy="72" r="2.5" fill="#3B6B4A" />
      {/* rising steam wisps */}
      <path d="M78 40 Q84 28 78 18" stroke="#FFFCF6" strokeWidth="3" fill="none" strokeLinecap="round" opacity="0.55" />
      <path d="M100 36 Q106 22 100 10" stroke="#FFFCF6" strokeWidth="3" fill="none" strokeLinecap="round" opacity="0.5" />
      <path d="M122 40 Q128 28 122 18" stroke="#FFFCF6" strokeWidth="3" fill="none" strokeLinecap="round" opacity="0.55" />
    </svg>
  );
}
